mapper.select:
SELECT m.*,c.state AS source_state,c.payload AS source_payload FROM transfer_serial_member m JOIN transfer_serial_command c ON c.id=m.source_command_id AND c.enterprise_id=m.enterprise_id
WHERE m.enterprise_id=#{e} AND m.transfer_id=#{transfer} AND m.serial_id IN #{sn}
ORDER BY m.serial_id FOR UPDATE
